<script setup lang="ts">
/**
 * "Record Inbound P.O. Delivery" (and "Correct delivery"): pick a purchase order, check the quality
 * of each received product, confirm. Everything shown comes from the purchase order records; the
 * Delivery # is generated by the server when the delivery is confirmed.
 *
 * Correct mode (a `delivery` is given): the same inspection table for a confirmed delivery, plus a
 * required reason. Stock is adjusted by the difference only (on the server).
 */
import { useForm } from '@inertiajs/vue3';
import { computed, ref, watch } from 'vue';
import { Search, X, AlertCircle, PackagePlus, Link2 } from '@lucide/vue';
import { useCurrency } from '@/composables/useCurrency';
import type { DeliveryDetail, ReceivableOrder } from '@/types/inboundDelivery';

const props = defineProps<{
    open: boolean;
    teamSlug: string;
    isAdmin: boolean;
    orders: ReceivableOrder[];
    products: { id: number; name: string; sku: string; unit?: string | null; is_active?: boolean }[];
    categories: string[];
    /** Correct mode: the confirmed delivery being corrected. */
    delivery?: DeliveryDetail | null;
}>();
const emit = defineEmits<{ close: []; saved: [] }>();

const { formatMoney } = useCurrency();
const today = () => new Date().toLocaleDateString('en-CA');
const isCorrection = computed(() => !!props.delivery);
const rejectionCategories = [
    ['defective', 'Defective'], ['damaged', 'Damaged'], ['incorrect_item', 'Incorrect item'],
    ['nonconforming_spec', 'Does not meet specification'], ['shortage_in_pack', 'Short in pack'], ['other', 'Other'],
] as const;
const standardCategories = ['Breakers', 'Lighting', 'Wiring', 'Controls', 'Tools', 'General'];
const categoryOptions = computed(() => [...new Set([...standardCategories, ...props.categories])]);

interface Row {
    key: number; // purchase order line id (record) or delivery item id (correct)
    item_sku: string | null;
    description: string;
    ordered: number | null;
    previously_received: number | null;
    remaining: number | null;
    unit_cost: number | null;
    unit_of_measure: string | null;
    extended_cost: number | null;
    product: { id: number; sku: string; name: string; via?: string } | null;
    received: number | null;
    accepted: number | null;
    rejected: number | null;
    remarks: string;
    category: string;
    overReason: string;
    productAction: '' | 'link' | 'create';
    productId: number | null;
    newCategory: string;
    inspected: boolean;
}

const search = ref('');
const selectedPo = ref<string | null>(null);
const rows = ref<Row[]>([]);
const form = useForm({
    delivery_date: today(),
    supplier_document_number: '',
    notes: '',
    reason: '',
    submission_key: '',
});
const order = computed(() => props.orders.find((o) => o.po_number === selectedPo.value) ?? null);
const filteredOrders = computed(() => {
    const q = search.value.trim().toLowerCase();
    if (!q) return props.orders;
    return props.orders.filter((o) => o.po_number.toLowerCase().includes(q) || (o.supplier?.name ?? '').toLowerCase().includes(q)
        || o.lines.some((l) => l.description.toLowerCase().includes(q) || (l.item_sku ?? '').toLowerCase().includes(q)));
});

const blankInspection = { remarks: '', category: '', overReason: '', productAction: '' as const, productId: null, newCategory: 'General', inspected: false };

const selectOrder = (poNumber: string) => {
    selectedPo.value = poNumber;
    const o = props.orders.find((x) => x.po_number === poNumber);
    rows.value = (o?.lines ?? []).map((l) => ({
        key: l.id, item_sku: l.item_sku, description: l.description, ordered: l.quantity, previously_received: l.previously_received, remaining: l.remaining,
        unit_cost: l.unit_cost, unit_of_measure: l.unit_of_measure, extended_cost: l.extended_cost, product: l.product,
        received: null, accepted: null, rejected: 0, ...blankInspection,
    }));
    form.clearErrors();
};

const reset = () => {
    form.reset();
    form.clearErrors();
    form.delivery_date = today();
    form.submission_key = crypto.randomUUID();
    search.value = '';
    selectedPo.value = null;
    rows.value = [];
    if (props.delivery) {
        const d = props.delivery;
        form.delivery_date = d.delivery_date;
        form.supplier_document_number = d.supplier_document_number ?? '';
        rows.value = d.items.filter((i) => i.status !== 'Cancelled').map((i) => ({
            key: i.id, item_sku: i.item_sku, description: i.description, ordered: i.ordered_quantity, previously_received: i.previously_received, remaining: i.remaining,
            unit_cost: i.unit_cost, unit_of_measure: i.unit_of_measure, extended_cost: i.extended_cost, product: i.product,
            received: i.received_quantity, accepted: i.accepted_quantity ?? i.received_quantity, rejected: i.rejected_quantity ?? 0,
            ...blankInspection, remarks: i.inspection_remarks ?? '', category: i.rejection_category ?? '', overReason: i.over_receipt_reason ?? '', inspected: true,
        }));
    }
};
watch(() => [props.open, props.delivery?.id], ([open]) => { if (open) reset(); }, { immediate: true });

// Accepted + rejected always add up to received: changing one works out the other.
const n = (v: number | null) => (Number.isFinite(Number(v)) && v !== null && (v as unknown) !== '' ? Number(v) : 0);
const onReceived = (r: Row) => {
    if (n(r.rejected) > n(r.received)) r.rejected = 0;
    r.accepted = Math.max(0, n(r.received) - n(r.rejected));
};
const onAccepted = (r: Row) => { if (n(r.accepted) <= n(r.received)) r.rejected = n(r.received) - n(r.accepted); };
const onRejected = (r: Row) => { if (n(r.rejected) <= n(r.received)) r.accepted = n(r.received) - n(r.rejected); };

const qualityStatus = (r: Row) => {
    if (n(r.received) <= 0) return null;
    if (n(r.rejected) === 0) return 'Passed';
    if (n(r.accepted) === 0) return 'Failed';
    return 'Partially Passed';
};
const statusClass: Record<string, string> = {
    Passed: 'border-emerald-200 bg-emerald-50 text-emerald-700',
    'Partially Passed': 'border-amber-200 bg-amber-50 text-amber-800',
    Failed: 'border-rose-200 bg-rose-50 text-rose-700',
};
const overReceived = (r: Row) => r.remaining !== null && n(r.received) > r.remaining;
const needsProduct = (r: Row) => !r.product && n(r.accepted) > 0;

/** What is wrong with a row, shown under it and blocking the confirm button. */
const rowProblems = (r: Row): string[] => {
    const p: string[] = [];
    const received = n(r.received);
    if (received < 0 || n(r.accepted) < 0 || n(r.rejected) < 0) p.push('Quantities cannot be negative.');
    if (received === 0) {
        if (isCorrection.value) p.push('Received quantity must be at least 1.');
        return p;
    }
    if (n(r.accepted) + n(r.rejected) !== received) p.push(`Accepted + rejected must equal the ${received} received (now ${n(r.accepted) + n(r.rejected)}).`);
    if (overReceived(r)) {
        if (!props.isAdmin) p.push(`Only ${r.remaining} still owed. Receiving more needs an administrator.`);
        else if (!r.overReason.trim()) p.push('Give the reason for receiving more than is owed.');
    }
    if (n(r.rejected) > 0 && !r.remarks.trim()) p.push('Describe why units were rejected in the inspection remarks.');
    if (needsProduct(r)) {
        if (!r.productAction) p.push('Not in inventory yet: link it to an existing product or create a new one.');
        else if (r.productAction === 'link' && !r.productId) p.push('Choose the inventory product.');
    }
    if (!isCorrection.value && !r.inspected) p.push('Tick "Quality checked" after inspecting this product.');
    return p;
};
const receivedRows = computed(() => rows.value.filter((r) => n(r.received) > 0));
const canSubmit = computed(() => {
    if (form.processing) return false;
    if (isCorrection.value) return !!form.reason.trim() && rows.value.every((r) => rowProblems(r).length === 0);
    return !!order.value && receivedRows.value.length > 0 && rows.value.every((r) => rowProblems(r).length === 0);
});

// Server messages: "lines.2.accepted_quantity" → row 2.
const serverErrors = computed(() => form.errors as Record<string, string>);
const rowServerErrors = (index: number) => Object.entries(serverErrors.value).filter(([k]) => k.startsWith(`lines.${index}.`)).map(([, v]) => v);
const generalErrors = computed(() => Object.entries(serverErrors.value).filter(([k]) => !k.startsWith('lines.')).map(([, v]) => v));

const payloadLine = (r: Row) => ({
    received_quantity: n(r.received),
    accepted_quantity: n(r.accepted),
    rejected_quantity: n(r.rejected),
    inspection_remarks: r.remarks.trim() || null,
    rejection_category: n(r.rejected) > 0 && r.category ? r.category : null,
    over_receipt_reason: overReceived(r) ? r.overReason.trim() || null : null,
    product_action: needsProduct(r) ? r.productAction || null : null,
    product_id: needsProduct(r) && r.productAction === 'link' ? r.productId : null,
    category: needsProduct(r) && r.productAction === 'create' ? r.newCategory.trim() || 'General' : null,
});

const submit = () => {
    if (!canSubmit.value) return;
    const options = { preserveScroll: true, onSuccess: () => emit('saved') };
    if (isCorrection.value && props.delivery) {
        form.transform((d) => ({
            reason: d.reason.trim(),
            delivery_date: d.delivery_date,
            supplier_document_number: d.supplier_document_number.trim() || null,
            lines: rows.value.map((r) => ({ delivery_id: r.key, ...payloadLine(r) })),
        })).put(`/${props.teamSlug}/deliveries/inbound/${props.delivery.id}`, options);
        return;
    }
    form.transform((d) => ({
        po_number: selectedPo.value,
        delivery_date: d.delivery_date,
        supplier_document_number: d.supplier_document_number.trim() || null,
        notes: d.notes.trim() || null,
        submission_key: d.submission_key,
        // Products that did not arrive are sent with 0 received and skipped by the server.
        lines: rows.value.map((r) => ({ purchase_order_id: r.key, inspected: r.inspected, ...payloadLine(r) })),
    })).post(`/${props.teamSlug}/deliveries/inbound`, options);
};

const fmtDate = (d: string | null | undefined) => {
    if (!d) return '—';
    const date = new Date(`${d.slice(0, 10)}T00:00:00`);
    return isNaN(date.getTime()) ? d : date.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
};
const money = (v: number | null) => (v === null ? '—' : formatMoney(v));
const minDate = computed(() => (isCorrection.value ? props.delivery?.order_date : order.value?.po_date) ?? undefined);
</script>

<template>
    <div v-if="open" class="fixed inset-0 z-50 flex items-center justify-center bg-black/70 p-4" @click.self="emit('close')">
        <form
            class="flex max-h-[92vh] w-full max-w-6xl flex-col overflow-hidden rounded-xl border border-gray-200 bg-card shadow-xl"
            role="dialog"
            aria-modal="true"
            aria-labelledby="inbound-recorder-title"
            data-test="inbound-recorder"
            @submit.prevent="submit"
        >
            <div class="flex items-start justify-between gap-3 border-b border-gray-200 px-6 py-4">
                <div class="min-w-0">
                    <h3 id="inbound-recorder-title" class="text-lg font-semibold text-foreground">
                        {{ isCorrection ? `Correct delivery ${delivery?.delivery_number}` : 'Record Inbound P.O. Delivery' }}
                    </h3>
                    <p class="mt-0.5 text-xs text-muted-foreground">
                        <template v-if="isCorrection">Stock is adjusted by the difference only. Your name, the time, the reason and the old and new values are recorded.</template>
                        <template v-else>Check the quality of each product that arrived. Only accepted units are added to inventory. The Delivery # is generated when you confirm.</template>
                    </p>
                </div>
                <button type="button" class="rounded-lg p-1 text-muted-foreground hover:bg-gray-100" aria-label="Close" @click="emit('close')"><X class="size-5" /></button>
            </div>

            <div class="min-h-0 flex-1 space-y-6 overflow-y-auto px-6 py-5">
                <!-- A. Select Purchase Order -->
                <section v-if="!isCorrection">
                    <label class="field-label" for="ib-po-search">Select Purchase Order</label>
                    <div v-if="!order">
                        <div class="relative">
                            <Search class="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-gray-400" />
                            <input id="ib-po-search" v-model="search" type="search" class="field-control pl-9" placeholder="Search by PO number, supplier, product or SKU" autocomplete="off" data-test="po-search" />
                        </div>
                        <ul class="mt-2 max-h-64 divide-y divide-gray-100 overflow-y-auto rounded-xl border border-gray-200" role="listbox" aria-label="Purchase orders with goods still owed">
                            <li v-if="!orders.length" class="p-4 text-sm text-muted-foreground">No purchase order is waiting for goods. Only Pending and Partially Received orders appear here.</li>
                            <li v-else-if="!filteredOrders.length" class="p-4 text-sm text-muted-foreground">No purchase order matches “{{ search }}”.</li>
                            <li v-for="o in filteredOrders" :key="o.po_number">
                                <button type="button" role="option" class="flex w-full flex-wrap items-center justify-between gap-2 px-4 py-3 text-left hover:bg-gray-50" :data-test="`po-option-${o.po_number}`" @click="selectOrder(o.po_number)">
                                    <span class="min-w-0">
                                        <span class="font-mono text-sm font-semibold text-foreground">{{ o.po_number }}</span>
                                        <span class="ml-2 text-sm text-gray-700">{{ o.supplier?.name ?? 'No supplier' }}</span>
                                    </span>
                                    <span class="text-xs text-muted-foreground">{{ fmtDate(o.po_date) }} · {{ o.lines.length }} product(s) open · {{ o.status }}</span>
                                </button>
                            </li>
                        </ul>
                    </div>
                    <div v-else class="flex flex-wrap items-center justify-between gap-2 rounded-xl border border-gray-200 bg-gray-50 px-4 py-2.5">
                        <span class="font-mono text-sm font-semibold">{{ order.po_number }}</span>
                        <button type="button" class="text-xs font-medium text-brand hover:underline" @click="selectedPo = null; rows = []">Change purchase order</button>
                    </div>
                </section>

                <!-- B. Purchase Order Information -->
                <section v-if="order || isCorrection" class="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-5">
                    <div class="rounded-xl border border-gray-200 px-4 py-3">
                        <div class="text-xs text-muted-foreground">Purchase Order Number</div>
                        <div class="font-mono text-sm font-semibold" data-test="po-info-number">{{ isCorrection ? delivery?.purchase_order_number ?? '—' : order?.po_number }}</div>
                    </div>
                    <div class="rounded-xl border border-gray-200 px-4 py-3">
                        <div class="text-xs text-muted-foreground">Order Date</div>
                        <div class="text-sm font-medium">{{ fmtDate(isCorrection ? delivery?.order_date : order?.po_date) }}</div>
                    </div>
                    <div class="rounded-xl border border-gray-200 px-4 py-3">
                        <div class="text-xs text-muted-foreground">Supplier Name</div>
                        <div class="text-sm font-medium">{{ (isCorrection ? delivery?.supplier : order?.supplier?.name) ?? '—' }}</div>
                    </div>
                    <div>
                        <label class="field-label" for="ib-date">Delivery date</label>
                        <input id="ib-date" v-model="form.delivery_date" type="date" :min="minDate" :max="today()" required class="field-control" />
                        <p class="mt-1 text-[11px] text-muted-foreground">Today by default. Change it only to correct the date.</p>
                    </div>
                    <div>
                        <label class="field-label" for="ib-doc">Supplier delivery doc. no. (optional)</label>
                        <input id="ib-doc" v-model="form.supplier_document_number" type="text" maxlength="100" class="field-control" />
                    </div>
                </section>

                <!-- C. Ordered Products -->
                <section v-if="rows.length">
                    <h4 class="mb-2 text-sm font-semibold text-foreground">Ordered Products</h4>
                    <div class="overflow-x-auto rounded-xl border border-gray-200">
                        <table class="w-full text-left text-xs" data-test="ordered-products">
                            <thead class="border-b border-gray-200 bg-gray-50 font-semibold text-muted-foreground">
                                <tr>
                                    <th class="whitespace-nowrap px-3 py-2 text-right">QUANTITY</th>
                                    <th class="whitespace-nowrap px-3 py-2">ITEM/SKU Number</th>
                                    <th class="px-3 py-2">Description</th>
                                    <th class="whitespace-nowrap px-3 py-2 text-right">UNIT COST</th>
                                    <th class="whitespace-nowrap px-3 py-2">U/M</th>
                                    <th class="whitespace-nowrap px-3 py-2 text-right">EXTENDED COST</th>
                                </tr>
                            </thead>
                            <tbody class="divide-y divide-gray-100">
                                <tr v-for="r in rows" :key="r.key">
                                    <td class="px-3 py-2 text-right font-medium">{{ r.ordered ?? '—' }}</td>
                                    <td class="whitespace-nowrap px-3 py-2 font-mono">{{ r.item_sku || '—' }}</td>
                                    <td class="min-w-48 px-3 py-2">{{ r.description }}</td>
                                    <td class="whitespace-nowrap px-3 py-2 text-right">{{ money(r.unit_cost) }}</td>
                                    <td class="whitespace-nowrap px-3 py-2">{{ r.unit_of_measure || '—' }}</td>
                                    <td class="whitespace-nowrap px-3 py-2 text-right font-medium">{{ money(r.extended_cost) }}</td>
                                </tr>
                            </tbody>
                        </table>
                    </div>
                </section>

                <!-- D. Check Quality -->
                <section v-if="rows.length">
                    <h4 class="text-sm font-semibold text-foreground">Check Quality</h4>
                    <p class="mb-3 text-xs text-muted-foreground">
                        Enter what actually arrived. Leave a product at 0 if it did not come; it stays owed. Rejected units are never added to stock.
                    </p>
                    <div class="space-y-3">
                        <div v-for="(r, index) in rows" :key="r.key" class="rounded-xl border border-gray-200 p-4" :data-test="`quality-row-${index}`">
                            <div class="flex flex-wrap items-start justify-between gap-2">
                                <div class="min-w-0">
                                    <div class="text-sm font-medium text-foreground">{{ r.description }}</div>
                                    <div class="text-xs text-muted-foreground">
                                        Supplier SKU {{ r.item_sku || '—' }} ·
                                        <template v-if="r.product">Inventory {{ r.product.sku }} {{ r.product.name }}<template v-if="r.product.via === 'supplier_sku'"> (matched by supplier SKU)</template></template>
                                        <template v-else>Not in inventory yet</template>
                                    </div>
                                </div>
                                <span v-if="qualityStatus(r)" class="inline-flex items-center rounded-md border px-2 py-0.5 text-xs font-medium" :class="statusClass[qualityStatus(r)!]" data-test="quality-status">{{ qualityStatus(r) }}</span>
                            </div>

                            <div class="mt-3 grid grid-cols-3 gap-3 sm:grid-cols-6">
                                <div>
                                    <div class="field-label">Ordered</div>
                                    <div class="py-2 text-sm font-medium">{{ r.ordered ?? '—' }}</div>
                                </div>
                                <div>
                                    <div class="field-label">Previously received</div>
                                    <div class="py-2 text-sm font-medium">{{ r.previously_received ?? '—' }}</div>
                                </div>
                                <div>
                                    <div class="field-label">Remaining</div>
                                    <div class="py-2 text-sm font-medium">{{ r.remaining ?? '—' }}</div>
                                </div>
                                <div>
                                    <label class="field-label" :for="`ib-rec-${index}`">Received</label>
                                    <input :id="`ib-rec-${index}`" v-model.number="r.received" type="number" min="0" step="1" inputmode="numeric" class="field-control" placeholder="0" @input="onReceived(r)" />
                                </div>
                                <div>
                                    <label class="field-label" :for="`ib-acc-${index}`">Accepted</label>
                                    <input :id="`ib-acc-${index}`" v-model.number="r.accepted" type="number" min="0" step="1" inputmode="numeric" class="field-control" :disabled="n(r.received) <= 0" @input="onAccepted(r)" />
                                </div>
                                <div>
                                    <label class="field-label" :for="`ib-rej-${index}`">Rejected</label>
                                    <input :id="`ib-rej-${index}`" v-model.number="r.rejected" type="number" min="0" step="1" inputmode="numeric" class="field-control" :disabled="n(r.received) <= 0" @input="onRejected(r)" />
                                </div>
                            </div>

                            <template v-if="n(r.received) > 0">
                                <div class="mt-3 grid grid-cols-1 gap-3" :class="n(r.rejected) > 0 ? 'sm:grid-cols-[1fr_14rem]' : ''">
                                    <div>
                                        <label class="field-label" :for="`ib-rem-${index}`">Inspection remarks {{ n(r.rejected) > 0 ? '(why units were rejected)' : '(optional)' }}</label>
                                        <input :id="`ib-rem-${index}`" v-model="r.remarks" type="text" maxlength="1000" class="field-control" placeholder="Condition of the goods, discrepancies…" />
                                    </div>
                                    <div v-if="n(r.rejected) > 0">
                                        <label class="field-label" :for="`ib-cat-${index}`">Rejection type</label>
                                        <select :id="`ib-cat-${index}`" v-model="r.category" class="field-control">
                                            <option value="">Other</option>
                                            <option v-for="[value, label] in rejectionCategories.filter(([v]) => v !== 'other')" :key="value" :value="value">{{ label }}</option>
                                        </select>
                                    </div>
                                </div>

                                <div v-if="overReceived(r) && isAdmin" class="mt-3">
                                    <label class="field-label" :for="`ib-over-${index}`">Reason for receiving more than the {{ r.remaining }} owed (administrator)</label>
                                    <input :id="`ib-over-${index}`" v-model="r.overReason" type="text" maxlength="1000" class="field-control" />
                                </div>

                                <!-- Not in inventory: the user decides; never matched by description. -->
                                <fieldset v-if="needsProduct(r)" class="mt-3 rounded-xl border border-amber-200 bg-amber-50/60 p-3">
                                    <legend class="px-1 text-xs font-medium text-amber-900">This product is not in inventory yet</legend>
                                    <div class="flex flex-wrap gap-4 text-sm">
                                        <label class="inline-flex items-center gap-2"><input v-model="r.productAction" type="radio" value="link" class="accent-[#4b5320]" /> <Link2 class="size-4 text-gray-500" /> Link to an existing product</label>
                                        <label class="inline-flex items-center gap-2"><input v-model="r.productAction" type="radio" value="create" class="accent-[#4b5320]" /> <PackagePlus class="size-4 text-gray-500" /> Create a new product</label>
                                    </div>
                                    <div v-if="r.productAction === 'link'" class="mt-2">
                                        <label class="sr-only" :for="`ib-link-${index}`">Inventory product</label>
                                        <select :id="`ib-link-${index}`" v-model="r.productId" class="field-control">
                                            <option :value="null" disabled>Choose the inventory product</option>
                                            <option v-for="p in products" :key="p.id" :value="p.id">{{ p.sku }} · {{ p.name }}{{ p.is_active === false ? ' (incomplete)' : '' }}</option>
                                        </select>
                                    </div>
                                    <div v-else-if="r.productAction === 'create'" class="mt-2 grid grid-cols-1 gap-2 sm:grid-cols-[14rem_1fr] sm:items-center">
                                        <div>
                                            <label class="field-label" :for="`ib-newcat-${index}`">Category (sets the SKU prefix)</label>
                                            <input :id="`ib-newcat-${index}`" v-model="r.newCategory" type="text" maxlength="100" :list="`ib-cats-${index}`" class="field-control" />
                                            <datalist :id="`ib-cats-${index}`"><option v-for="c in categoryOptions" :key="c" :value="c" /></datalist>
                                        </div>
                                        <p class="text-xs text-amber-900">
                                            A new SKU is generated (the supplier's code {{ r.item_sku || '' }} is kept separately). It is saved with this supplier and a unit cost of {{ money(r.unit_cost) }},
                                            and stays Incomplete until a selling price is entered on the Inventory page.
                                        </p>
                                    </div>
                                </fieldset>

                                <label v-if="!isCorrection" class="mt-3 inline-flex items-center gap-2 text-sm font-medium text-foreground">
                                    <input v-model="r.inspected" type="checkbox" class="size-4 accent-[#4b5320]" :data-test="`inspected-${index}`" /> Quality checked
                                </label>
                            </template>

                            <ul v-if="rowProblems(r).length || rowServerErrors(index).length" class="mt-2 space-y-0.5">
                                <li v-for="msg in [...rowServerErrors(index), ...rowProblems(r)]" :key="msg" class="flex items-start gap-1.5 text-xs text-rose-600">
                                    <AlertCircle class="mt-px size-3.5 shrink-0" /> {{ msg }}
                                </li>
                            </ul>
                        </div>
                    </div>
                </section>

                <section v-if="isCorrection">
                    <label class="field-label" for="ib-reason">Reason for the correction</label>
                    <textarea id="ib-reason" v-model="form.reason" rows="2" maxlength="500" required class="field-control" placeholder="e.g. two units found damaged after unpacking"></textarea>
                </section>
                <section v-else-if="order">
                    <label class="field-label" for="ib-notes">Delivery remarks (optional)</label>
                    <input id="ib-notes" v-model="form.notes" type="text" maxlength="1000" class="field-control" />
                </section>
            </div>

            <div class="flex flex-col gap-3 border-t border-gray-200 px-6 py-4 sm:flex-row sm:items-center sm:justify-between">
                <div class="min-w-0 text-xs">
                    <p v-for="msg in generalErrors" :key="msg" class="text-rose-600" role="alert">{{ msg }}</p>
                    <p v-if="!generalErrors.length && !isCorrection && order" class="text-muted-foreground">
                        {{ receivedRows.length }} of {{ rows.length }} product(s) received · {{ receivedRows.reduce((s, r) => s + n(r.accepted), 0) }} unit(s) will be added to inventory.
                    </p>
                </div>
                <div class="flex flex-col-reverse gap-3 sm:flex-row">
                    <button type="button" class="secondary-button" @click="emit('close')">Cancel</button>
                    <button type="submit" class="brand-button" :disabled="!canSubmit" data-test="confirm-delivery">
                        {{ form.processing ? 'Saving…' : isCorrection ? 'Save correction' : 'Confirm Delivery' }}
                    </button>
                </div>
            </div>
        </form>
    </div>
</template>
